window.DC_TRANSLATIONS = {"Zum Inhalt springen": {"fr": "Aller au contenu", "en": "Skip to content", "es": "Saltar al contenido", "it": "Vai al contenuto"}, "Startseite": {"fr": "Accueil", "en": "Home", "es": "Inicio", "it": "Home"}, "Leistungen": {"fr": "Services", "en": "Services", "es": "Servicios", "it": "Servizi"}, "Projekte": {"fr": "Projets", "en": "Projects", "es": "Proyectos", "it": "Progetti"}, "Über uns": {"fr": "À propos", "en": "About us", "es": "Nosotros", "it": "Chi siamo"}, "Kontakt": {"fr": "Contact", "en": "Contact", "es": "Contacto", "it": "Contatti"}, "Webprojekt anfragen": {"fr": "Demander un projet web", "en": "Discuss your website", "es": "Solicitar un proyecto web", "it": "Richiedi un progetto web"}, "Webdesign": {"fr": "Webdesign", "en": "Web design", "es": "Diseño web", "it": "Web design"}, "Schweiz für": {"fr": "en Suisse pour", "en": "in Switzerland for", "es": "en Suiza para", "it": "in Svizzera per"}, "Unternehmen.": {"fr": "les entreprises.", "en": "businesses.", "es": "empresas.", "it": "le aziende."}, "Webdesign-Projekte ansehen": {"fr": "Voir les projets web", "en": "View web design projects", "es": "Ver proyectos web", "it": "Vedi i progetti web"}, "Digital Concepts entwickelt individuelle Websites, Landingpages und Online-Shops für Unternehmen in der Schweiz – responsive, klar strukturiert und darauf ausgerichtet, Besucher zu Kunden zu machen.": {"fr": "Digital Concepts développe des sites sur mesure, des landing pages et des boutiques en ligne pour les entreprises en Suisse : responsives, structurés et conçus pour transformer les visiteurs en clients.", "en": "Digital Concepts builds custom websites, landing pages and online stores for businesses in Switzerland — responsive, clearly structured and designed to turn visitors into customers.", "es": "Digital Concepts desarrolla sitios web a medida, landing pages y tiendas online para empresas en Suiza: adaptables, bien estructurados y diseñados para convertir visitantes en clientes.", "it": "Digital Concepts sviluppa siti su misura, landing page e negozi online per le aziende in Svizzera: responsive, ben strutturati e pensati per trasformare i visitatori in clienti."}, "Beispielseite": {"fr": "Site exemple", "en": "Example website", "es": "Sitio de ejemplo", "it": "Sito di esempio"}, "Ihre Marke, klar präsentiert.": {"fr": "Votre marque, clairement présentée.", "en": "Your brand, clearly presented.", "es": "Tu marca, presentada con claridad.", "it": "Il tuo marchio, presentato con chiarezza."}, "Klar auf jedem Gerät.": {"fr": "Clair sur tous les écrans.", "en": "Clear on every device.", "es": "Claro en cualquier dispositivo.", "it": "Chiaro su ogni dispositivo."}, "Positionierung": {"fr": "Positionnement", "en": "Positioning", "es": "Posicionamiento", "it": "Posizionamento"}, "Individuelles Webdesign. Klar umgesetzt.": {"fr": "Un webdesign sur mesure. Une réalisation claire.", "en": "Custom web design. Clearly delivered.", "es": "Diseño web a medida. Ejecución clara.", "it": "Web design su misura. Realizzazione chiara."}, "Wir verbinden modernes Webdesign, effiziente Entwicklung und klare Kommunikation. So entsteht eine professionelle Website, die zu Ihrem Unternehmen passt, auf allen Geräten überzeugt und ohne unnötig komplizierte Prozesse realisiert wird.": {"fr": "Nous associons design moderne, développement efficace et communication claire pour créer un site professionnel adapté à votre entreprise, convaincant sur tous les écrans et réalisé sans procédures inutiles.", "en": "We combine modern web design, efficient development and clear communication to create a professional website that fits your business, works on every device and avoids unnecessarily complex processes.", "es": "Combinamos diseño moderno, desarrollo eficiente y comunicación clara para crear una web profesional adaptada a tu empresa, eficaz en todos los dispositivos y sin procesos innecesariamente complejos.", "it": "Uniamo design moderno, sviluppo efficiente e comunicazione chiara per creare un sito professionale adatto alla tua azienda, efficace su ogni dispositivo e senza processi inutilmente complessi."}, "Individuelles Webdesign": {"fr": "Webdesign sur mesure", "en": "Custom web design", "es": "Diseño web a medida", "it": "Web design su misura"}, "Keine Website von der Stange: Gestaltung, Struktur und Nutzerführung werden auf Ihre Marke und Ihr Unternehmen abgestimmt.": {"fr": "Pas de site standard : le design, la structure et le parcours utilisateur sont adaptés à votre marque et à votre entreprise.", "en": "No off-the-shelf website: design, structure and navigation are tailored to your brand and business.", "es": "Nada de webs genéricas: el diseño, la estructura y la navegación se adaptan a tu marca y empresa.", "it": "Niente siti standard: design, struttura e navigazione sono adattati al tuo marchio e alla tua azienda."}, "Responsive Webentwicklung": {"fr": "Développement web responsive", "en": "Responsive web development", "es": "Desarrollo web adaptable", "it": "Sviluppo web responsive"}, "Optimierte Darstellung und intuitive Bedienung auf Smartphone, Tablet und Desktop.": {"fr": "Un affichage optimisé et une navigation intuitive sur smartphone, tablette et ordinateur.", "en": "Optimized display and intuitive navigation on phones, tablets and desktops.", "es": "Visualización optimizada y navegación intuitiva en móvil, tableta y ordenador.", "it": "Visualizzazione ottimizzata e navigazione intuitiva su smartphone, tablet e computer."}, "Effiziente Website-Umsetzung": {"fr": "Réalisation web efficace", "en": "Efficient website delivery", "es": "Creación web eficiente", "it": "Realizzazione web efficiente"}, "Moderne Arbeitsprozesse ermöglichen professionelle Unternehmenswebsites ohne die Kostenstruktur klassischer Grossagenturen.": {"fr": "Des méthodes modernes permettent de créer des sites professionnels sans la structure de coûts des grandes agences traditionnelles.", "en": "Modern workflows deliver professional business websites without the cost structure of traditional large agencies.", "es": "Los procesos modernos permiten crear webs profesionales sin la estructura de costes de las grandes agencias tradicionales.", "it": "Processi moderni permettono di creare siti professionali senza la struttura di costi delle grandi agenzie tradizionali."}, "Webdesign-Leistungen für Ihr Unternehmen.": {"fr": "Des services web pour votre entreprise.", "en": "Web design services for your business.", "es": "Servicios web para tu empresa.", "it": "Servizi web per la tua azienda."}, "Landingpages": {"fr": "Landing pages", "en": "Landing pages", "es": "Landing pages", "it": "Landing page"}, "Conversion-orientierte Landingpages für Kampagnen, Dienstleistungen, Produkte und neue Angebote.": {"fr": "Des landing pages axées sur la conversion pour vos campagnes, services, produits et nouvelles offres.", "en": "Conversion-focused landing pages for campaigns, services, products and new offers.", "es": "Landing pages orientadas a la conversión para campañas, servicios, productos y nuevas ofertas.", "it": "Landing page orientate alla conversione per campagne, servizi, prodotti e nuove offerte."}, "Landingpages ansehen": {"fr": "Découvrir les landing pages", "en": "Explore landing pages", "es": "Ver landing pages", "it": "Scopri le landing page"}, "Unternehmenswebsites": {"fr": "Sites d’entreprise", "en": "Business websites", "es": "Sitios corporativos", "it": "Siti aziendali"}, "Professionelle Unternehmenswebsites, die Vertrauen schaffen, Leistungen verständlich erklären und Ihre Marke hochwertig präsentieren.": {"fr": "Des sites professionnels qui inspirent confiance, expliquent clairement vos services et mettent votre marque en valeur.", "en": "Professional business websites that build trust, explain services clearly and showcase your brand.", "es": "Webs profesionales que generan confianza, explican tus servicios con claridad y destacan tu marca.", "it": "Siti professionali che ispirano fiducia, spiegano chiaramente i servizi e valorizzano il tuo marchio."}, "Websites ansehen": {"fr": "Découvrir les sites", "en": "Explore websites", "es": "Ver sitios web", "it": "Scopri i siti web"}, "Online-Shops": {"fr": "Boutiques en ligne", "en": "Online stores", "es": "Tiendas online", "it": "Negozi online"}, "Moderne Online-Shops mit klarer Navigation, überzeugender Produktdarstellung und responsiver Bedienung auf allen Geräten.": {"fr": "Des boutiques modernes avec une navigation claire, des produits mis en valeur et une utilisation adaptée à tous les écrans.", "en": "Modern online stores with clear navigation, compelling product presentation and responsive use on every device.", "es": "Tiendas modernas con navegación clara, productos bien presentados y uso adaptable a todos los dispositivos.", "it": "Negozi moderni con navigazione chiara, prodotti ben presentati e utilizzo responsive su ogni dispositivo."}, "Online-Shops ansehen": {"fr": "Découvrir les boutiques", "en": "Explore online stores", "es": "Ver tiendas online", "it": "Scopri i negozi online"}, "Individuelle Lösungen": {"fr": "Solutions sur mesure", "en": "Custom solutions", "es": "Soluciones a medida", "it": "Soluzioni su misura"}, "Individuelle Weblösungen und Funktionen, passgenau entwickelt für die Anforderungen Ihres Projekts.": {"fr": "Des solutions web et des fonctionnalités développées précisément pour les besoins de votre projet.", "en": "Custom web solutions and features built to match your project's requirements.", "es": "Soluciones y funciones web desarrolladas a medida de los requisitos de tu proyecto.", "it": "Soluzioni e funzioni web sviluppate su misura per le esigenze del tuo progetto."}, "Lösungen ansehen": {"fr": "Découvrir les solutions", "en": "Explore solutions", "es": "Ver soluciones", "it": "Scopri le soluzioni"}, "Jetzt Termin vereinbaren.": {"fr": "Prenez rendez-vous.", "en": "Book an appointment.", "es": "Reserva una cita.", "it": "Prenota un appuntamento."}, "Produkte, die verkaufen.": {"fr": "Des produits qui se vendent.", "en": "Products that sell.", "es": "Productos que venden.", "it": "Prodotti che vendono."}, "Digitale Werkzeuge für Ihr Team.": {"fr": "Des outils numériques pour votre équipe.", "en": "Digital tools for your team.", "es": "Herramientas digitales para tu equipo.", "it": "Strumenti digitali per il tuo team."}, "Modernisierung": {"fr": "Modernisation", "en": "Modernization", "es": "Modernización", "it": "Modernizzazione"}, "Website-Relaunch für einen modernen Auftritt.": {"fr": "Une refonte web pour une image moderne.", "en": "A website relaunch for a modern presence.", "es": "Renueva tu web para una imagen moderna.", "it": "Un restyling web per un'immagine moderna."}, "Der erste Eindruck Ihres Unternehmens entsteht häufig online. Mit einem Website-Relaunch verwandeln wir veraltete Seiten in moderne, schnelle und professionell strukturierte digitale Auftritte.": {"fr": "La première impression de votre entreprise se forme souvent en ligne. Nous transformons les sites vieillissants en présences numériques modernes, rapides et structurées.", "en": "Your business often makes its first impression online. Our website relaunch turns outdated pages into modern, fast and professionally structured digital presences.", "es": "La primera impresión de tu empresa suele surgir online. Transformamos páginas anticuadas en una presencia digital moderna, rápida y profesional.", "it": "La prima impressione della tua azienda nasce spesso online. Trasformiamo pagine obsolete in una presenza digitale moderna, veloce e professionale."}, "Vorher": {"fr": "Avant", "en": "Before", "es": "Antes", "it": "Prima"}, "Nachher": {"fr": "Après", "en": "After", "es": "Después", "it": "Dopo"}, "Ihr Partner seit 1998": {"fr": "Votre partenaire depuis 1998", "en": "Your partner since 1998", "es": "Tu socio desde 1998", "it": "Il tuo partner dal 1998"}, "Produkte": {"fr": "Produits", "en": "Products", "es": "Productos", "it": "Prodotti"}, "Neu:": {"fr": "Nouveau :", "en": "New:", "es": "Nuevo:", "it": "Novità:"}, "Unsere Öffnungszeiten wurden angepasst. Bitte beachten Sie die Hinweise.": {"fr": "Nos horaires ont changé. Veuillez consulter les informations.", "en": "Our opening hours have changed. Please check the notices.", "es": "Nuestro horario ha cambiado. Consulta los avisos.", "it": "I nostri orari sono cambiati. Consulta gli avvisi."}, "Herzlich willkommen auf unserer Homepage. Wir freuen uns über Ihren Besuch und informieren Sie hier über unser Unternehmen, unsere Produkte sowie unsere Dienstleistungen. Für weitere Auskünfte stehen wir Ihnen gerne zur Verfügung.": {"fr": "Bienvenue sur notre site. Nous sommes heureux de vous présenter notre entreprise, nos produits et nos services. Nous restons à votre disposition pour toute information.", "en": "Welcome to our website. We are pleased to introduce our company, products and services. Please contact us for further information.", "es": "Te damos la bienvenida a nuestra web. Aquí presentamos nuestra empresa, productos y servicios. Estamos a tu disposición para más información.", "it": "Benvenuto sul nostro sito. Ti presentiamo la nostra azienda, i prodotti e i servizi. Restiamo a disposizione per ulteriori informazioni."}, "Bitte nutzen Sie das Kontaktformular oder rufen Sie uns während der Bürozeiten an.": {"fr": "Utilisez le formulaire de contact ou appelez-nous pendant les heures de bureau.", "en": "Use the contact form or call us during office hours.", "es": "Usa el formulario de contacto o llámanos en horario de oficina.", "it": "Usa il modulo di contatto o chiamaci durante gli orari d'ufficio."}, "Mehr erfahren": {"fr": "En savoir plus", "en": "Learn more", "es": "Más información", "it": "Scopri di più"}, "Besucher: 004 812 | Letzte Aktualisierung: 14.03.2011": {"fr": "Visiteurs : 004 812 — Mise à jour : 14.03.2011", "en": "Visitors: 004 812 — Last update: 14.03.2011", "es": "Visitantes: 004 812 — Actualización: 14.03.2011", "it": "Visitatori: 004 812 — Aggiornamento: 14.03.2011"}, "Präzision, auf die sich Kunden verlassen.": {"fr": "Une précision sur laquelle compter.", "en": "Precision customers can rely on.", "es": "Precisión en la que confiar.", "it": "Precisione su cui contare."}, "Seit 1998 fertigen wir Komponenten für Industrie und Handel – heute mit einem Auftritt, der das auch zeigt.": {"fr": "Depuis 1998, nous fabriquons des composants pour l’industrie et le commerce, avec aujourd’hui une image qui le reflète.", "en": "Since 1998, we have made components for industry and trade — now with a website that reflects it.", "es": "Desde 1998 fabricamos componentes para la industria y el comercio, ahora con una web que lo refleja.", "it": "Dal 1998 produciamo componenti per industria e commercio, oggi con un sito che lo dimostra."}, "Offerte anfragen": {"fr": "Demander un devis", "en": "Request a quote", "es": "Solicitar presupuesto", "it": "Richiedi un preventivo"}, "Beispielhafte Gegenüberstellung. Ziehen Sie den Regler, um den Unterschied zu sehen.": {"fr": "Comparaison illustrative. Faites glisser le curseur pour voir la différence.", "en": "Illustrative comparison. Drag the slider to see the difference.", "es": "Comparación ilustrativa. Arrastra el control para ver la diferencia.", "it": "Confronto illustrativo. Trascina il cursore per vedere la differenza."}, "Website-Relaunch anfragen": {"fr": "Demander une refonte web", "en": "Request a website relaunch", "es": "Solicitar una renovación web", "it": "Richiedi un restyling web"}, "Ausgewählte Webdesign-Projekte.": {"fr": "Une sélection de projets web.", "en": "Selected web design projects.", "es": "Proyectos web seleccionados.", "it": "Progetti web selezionati."}, "Beratung, die man versteht.": {"fr": "Des conseils que l’on comprend.", "en": "Advice that makes sense.", "es": "Asesoramiento que se entiende.", "it": "Consigli chiari."}, "Projekt 01": {"fr": "Projet 01", "en": "Project 01", "es": "Proyecto 01", "it": "Progetto 01"}, "Dienstleistung": {"fr": "Services", "en": "Services", "es": "Servicios", "it": "Servizi"}, "Konzeptvorschau für eine klar strukturierte Unternehmenswebsite im Dienstleistungsbereich. Das finale Kundenprojekt wird nach der Freigabe ergänzt.": {"fr": "Aperçu conceptuel d’un site d’entreprise structuré dans les services. Le projet client final sera ajouté après validation.", "en": "Concept preview of a clearly structured business website for the service sector. The final client project will be added after approval.", "es": "Vista conceptual de una web corporativa bien estructurada para servicios. El proyecto final se añadirá tras su aprobación.", "it": "Anteprima concettuale di un sito aziendale ben strutturato per i servizi. Il progetto finale sarà aggiunto dopo l'approvazione."}, "Konzept": {"fr": "Concept", "en": "Concept", "es": "Concepto", "it": "Concetto"}, "Entwicklung": {"fr": "Développement", "en": "Development", "es": "Desarrollo", "it": "Sviluppo"}, "Webdesign-Projekt ansehen": {"fr": "Voir le projet web", "en": "View website project", "es": "Ver proyecto web", "it": "Vedi il progetto web"}, "Sortiment, klar sortiert.": {"fr": "Un catalogue bien organisé.", "en": "A clearly organized range.", "es": "Un catálogo bien organizado.", "it": "Un catalogo ben organizzato."}, "Projekt 02": {"fr": "Projet 02", "en": "Project 02", "es": "Proyecto 02", "it": "Progetto 02"}, "Handel": {"fr": "Commerce", "en": "Retail", "es": "Comercio", "it": "Commercio"}, "Konzeptvorschau für einen responsiven Online-Shop mit klarer Produktnavigation. Die Struktur ist bereits auf ein reales Kundenprojekt ausgelegt.": {"fr": "Aperçu conceptuel d’une boutique responsive avec une navigation produit claire. La structure est déjà conçue pour un projet client réel.", "en": "Concept preview of a responsive online store with clear product navigation. The structure is already designed for a real client project.", "es": "Vista conceptual de una tienda adaptable con navegación de productos clara. La estructura ya está preparada para un proyecto real.", "it": "Anteprima concettuale di un negozio responsive con navigazione prodotti chiara. La struttura è già pensata per un progetto reale."}, "Online-Shop": {"fr": "Boutique en ligne", "en": "Online store", "es": "Tienda online", "it": "Negozio online"}, "Online-Shop-Projekt ansehen": {"fr": "Voir le projet e-commerce", "en": "View online store project", "es": "Ver proyecto de tienda online", "it": "Vedi il progetto e-commerce"}, "Angebot sichern.": {"fr": "Profitez de l’offre.", "en": "Secure your offer.", "es": "Aprovecha la oferta.", "it": "Approfitta dell'offerta."}, "Projekt 03": {"fr": "Projet 03", "en": "Project 03", "es": "Proyecto 03", "it": "Progetto 03"}, "Kampagne": {"fr": "Campagne", "en": "Campaign", "es": "Campaña", "it": "Campagna"}, "Konzeptvorschau für eine fokussierte Kampagnen-Landingpage. Das flexible Layout lässt sich nach der Freigabe direkt mit realen Projektdaten ergänzen.": {"fr": "Aperçu conceptuel d’une landing page de campagne ciblée. Après validation, le contenu réel du projet peut être intégré directement.", "en": "Concept preview of a focused campaign landing page. After approval, the flexible layout can be filled directly with real project content.", "es": "Vista conceptual de una landing page de campaña. Tras la aprobación, el diseño flexible permite incorporar contenido real del proyecto.", "it": "Anteprima concettuale di una landing page per campagne mirate. Dopo l'approvazione, il layout flessibile può accogliere i contenuti reali del progetto."}, "Copy-Struktur": {"fr": "Structure rédactionnelle", "en": "Copy structure", "es": "Estructura de textos", "it": "Struttura dei testi"}, "Landingpage-Projekt ansehen": {"fr": "Voir le projet landing page", "en": "View landing page project", "es": "Ver proyecto de landing page", "it": "Vedi il progetto landing page"}, "Aktuell zeigen wir beispielhafte Webdesign-Konzepte. Freigegebene Kundenprojekte werden mit Name, Branche, Projektbeschreibung, Leistungen und Bild ergänzt.": {"fr": "Nous présentons actuellement des concepts web illustratifs. Les projets clients approuvés seront ajoutés avec nom, secteur, description, prestations et visuels.", "en": "We currently show illustrative web design concepts. Approved client projects will be added with names, industries, descriptions, services and images.", "es": "Actualmente mostramos conceptos web ilustrativos. Los proyectos aprobados se añadirán con nombre, sector, descripción, servicios e imágenes.", "it": "Attualmente mostriamo concept web illustrativi. I progetti approvati saranno aggiunti con nome, settore, descrizione, servizi e immagini."}, "Ablauf": {"fr": "Étapes", "en": "Process", "es": "Proceso", "it": "Processo"}, "Von der Idee zur fertigen Unternehmenswebsite.": {"fr": "De l’idée au site d’entreprise finalisé.", "en": "From idea to finished business website.", "es": "De la idea a la web corporativa terminada.", "it": "Dall'idea al sito aziendale completo."}, "Unser Webdesign-Prozess führt in fünf klaren Schritten vom ersten Gespräch bis zum Launch. Sie wissen jederzeit, wo Ihr Projekt steht.": {"fr": "Notre processus vous accompagne en cinq étapes claires, du premier échange au lancement. Vous savez toujours où en est votre projet.", "en": "Our web design process takes five clear steps from the first conversation to launch. You always know where your project stands.", "es": "Nuestro proceso sigue cinco pasos claros, desde la primera conversación hasta el lanzamiento. Siempre sabrás en qué punto está tu proyecto.", "it": "Il nostro processo segue cinque fasi chiare, dal primo incontro al lancio. Saprai sempre a che punto è il progetto."}, "Kennenlernen": {"fr": "Premier échange", "en": "Getting acquainted", "es": "Primer contacto", "it": "Primo incontro"}, "Wir lernen Ihr Unternehmen, Ihre Zielgruppen sowie die Ziele und Anforderungen der neuen Website kennen.": {"fr": "Nous découvrons votre entreprise, vos publics cibles et les objectifs et besoins du nouveau site.", "en": "We learn about your business, target audiences and the goals and requirements of your new website.", "es": "Conocemos tu empresa, tu público y los objetivos y requisitos de la nueva web.", "it": "Conosciamo la tua azienda, il pubblico e gli obiettivi e requisiti del nuovo sito."}, "Wir definieren Seitenstruktur, Inhalte, Nutzerführung und die visuelle Richtung Ihres Webauftritts.": {"fr": "Nous définissons la structure, les contenus, les parcours et la direction visuelle de votre site.", "en": "We define your website's structure, content, navigation and visual direction.", "es": "Definimos la estructura, los contenidos, la navegación y la dirección visual de tu web.", "it": "Definiamo struttura, contenuti, navigazione e direzione visiva del sito."}, "Design & Entwicklung": {"fr": "Design et développement", "en": "Design & development", "es": "Diseño y desarrollo", "it": "Design e sviluppo"}, "Das Webdesign wird ausgearbeitet und als responsive Website technisch umgesetzt.": {"fr": "Le design est élaboré puis développé sous forme de site responsive.", "en": "We develop the design and build it as a responsive website.", "es": "Elaboramos el diseño y lo implementamos como una web adaptable.", "it": "Elaboriamo il design e lo realizziamo come sito responsive."}, "Optimierung": {"fr": "Optimisation", "en": "Optimization", "es": "Optimización", "it": "Ottimizzazione"}, "Wir prüfen mobile Darstellung, Ladegeschwindigkeit, Lesbarkeit und Benutzererlebnis auf allen wichtigen Geräten.": {"fr": "Nous vérifions l’affichage mobile, la rapidité, la lisibilité et l’expérience sur les principaux appareils.", "en": "We check mobile display, loading speed, readability and usability on all key devices.", "es": "Comprobamos la visualización móvil, la velocidad, la legibilidad y la experiencia en los dispositivos principales.", "it": "Verifichiamo visualizzazione mobile, velocità, leggibilità ed esperienza sui dispositivi principali."}, "Nach der finalen Prüfung und Ihrer Freigabe geht die neue Website online.": {"fr": "Après les dernières vérifications et votre accord, le nouveau site est mis en ligne.", "en": "After final checks and your approval, your new website goes live.", "es": "Tras las comprobaciones finales y tu aprobación, publicamos la nueva web.", "it": "Dopo le verifiche finali e la tua approvazione, il nuovo sito va online."}, "Zusammenarbeit": {"fr": "Collaboration", "en": "Collaboration", "es": "Colaboración", "it": "Collaborazione"}, "Warum Digital Concepts als Webagentur?": {"fr": "Pourquoi choisir Digital Concepts ?", "en": "Why choose Digital Concepts?", "es": "¿Por qué elegir Digital Concepts?", "it": "Perché scegliere Digital Concepts?"}, "Wir setzen auf eine persönliche, transparente und planbare Zusammenarbeit. So entsteht Webdesign, das zu Ihrem Unternehmen, Ihren Zielen und Ihren Nutzerinnen und Nutzern passt.": {"fr": "Nous privilégions une collaboration personnelle, transparente et prévisible pour créer un site adapté à votre entreprise, vos objectifs et vos utilisateurs.", "en": "We focus on personal, transparent and predictable collaboration to create web design that fits your business, goals and users.", "es": "Priorizamos una colaboración personal, transparente y planificada para crear una web adaptada a tu empresa, objetivos y usuarios.", "it": "Puntiamo su una collaborazione personale, trasparente e pianificabile per creare un sito adatto alla tua azienda, ai tuoi obiettivi e agli utenti."}, "Modernes Webdesign": {"fr": "Webdesign moderne", "en": "Modern web design", "es": "Diseño web moderno", "it": "Web design moderno"}, "Zeitgemässe Gestaltung mit klarer visueller Hierarchie – hochwertig, eigenständig und langfristig einsetzbar.": {"fr": "Un design actuel avec une hiérarchie visuelle claire : soigné, distinctif et durable.", "en": "Contemporary design with clear visual hierarchy — refined, distinctive and built to last.", "es": "Diseño actual con jerarquía visual clara: cuidado, distintivo y duradero.", "it": "Design contemporaneo con gerarchia visiva chiara: curato, distintivo e duraturo."}, "Persönliche Zusammenarbeit": {"fr": "Collaboration personnelle", "en": "Personal collaboration", "es": "Colaboración personal", "it": "Collaborazione personale"}, "Sie sprechen direkt mit den Personen, die Ihre Website konzipieren, gestalten und entwickeln.": {"fr": "Vous échangez directement avec les personnes qui conçoivent, dessinent et développent votre site.", "en": "You speak directly with the people who plan, design and develop your website.", "es": "Hablas directamente con quienes planifican, diseñan y desarrollan tu web.", "it": "Parli direttamente con chi progetta, disegna e sviluppa il sito."}, "Kurze Kommunikationswege": {"fr": "Communication directe", "en": "Direct communication", "es": "Comunicación directa", "it": "Comunicazione diretta"}, "Fragen und Entscheidungen werden direkt geklärt – ohne unnötige Zwischenstellen.": {"fr": "Les questions et décisions sont traitées directement, sans intermédiaires inutiles.", "en": "Questions and decisions are handled directly, without unnecessary intermediaries.", "es": "Las preguntas y decisiones se resuelven directamente, sin intermediarios innecesarios.", "it": "Domande e decisioni vengono affrontate direttamente, senza intermediari inutili."}, "Individuelle Weblösungen": {"fr": "Solutions web sur mesure", "en": "Custom web solutions", "es": "Soluciones web a medida", "it": "Soluzioni web su misura"}, "Funktionen und Projektumfang richten sich nach Ihrem Vorhaben, nicht nach einem starren Paket.": {"fr": "Les fonctionnalités et le périmètre dépendent de votre projet, pas d’un forfait rigide.", "en": "Features and scope follow your needs, rather than a rigid package.", "es": "Las funciones y el alcance se adaptan a tu proyecto, no a un paquete rígido.", "it": "Funzioni e portata seguono le esigenze del progetto, non un pacchetto rigido."}, "Effiziente Umsetzung": {"fr": "Réalisation efficace", "en": "Efficient delivery", "es": "Ejecución eficiente", "it": "Realizzazione efficiente"}, "Moderne Prozesse ermöglichen professionelle Webentwicklung ohne den Overhead einer Grossagentur.": {"fr": "Des processus modernes permettent un développement professionnel sans les frais de structure d’une grande agence.", "en": "Modern processes enable professional development without large-agency overheads.", "es": "Los procesos modernos permiten un desarrollo profesional sin los costes de estructura de una gran agencia.", "it": "Processi moderni consentono uno sviluppo professionale senza i costi strutturali di una grande agenzia."}, "Transparenter Projektablauf": {"fr": "Déroulement transparent", "en": "Transparent project process", "es": "Proceso transparente", "it": "Processo trasparente"}, "Sie wissen jederzeit, woran wir arbeiten, welche Entscheidungen anstehen und was als Nächstes folgt.": {"fr": "Vous savez toujours sur quoi nous travaillons, quelles décisions prendre et quelle sera la prochaine étape.", "en": "You always know what we are working on, which decisions are due and what comes next.", "es": "Siempre sabes en qué trabajamos, qué decisiones hay que tomar y cuál es el siguiente paso.", "it": "Sai sempre su cosa lavoriamo, quali decisioni prendere e quale sarà il prossimo passo."}, "Fokus auf Benutzererlebnis": {"fr": "Priorité à l’expérience utilisateur", "en": "Focus on user experience", "es": "Experiencia de usuario primero", "it": "Attenzione all'esperienza utente"}, "Klare Inhalte und intuitive Nutzerführung helfen Besucherinnen und Besuchern, schnell die richtigen Informationen zu finden.": {"fr": "Des contenus clairs et une navigation intuitive permettent aux visiteurs de trouver rapidement les bonnes informations.", "en": "Clear content and intuitive navigation help visitors find the right information quickly.", "es": "Los contenidos claros y la navegación intuitiva ayudan a encontrar rápidamente la información correcta.", "it": "Contenuti chiari e navigazione intuitiva aiutano a trovare rapidamente le informazioni giuste."}, "Responsive Entwicklung": {"fr": "Développement responsive", "en": "Responsive development", "es": "Desarrollo adaptable", "it": "Sviluppo responsive"}, "Ihre Website wird für Smartphone, Tablet und Desktop entwickelt und geprüft.": {"fr": "Votre site est développé et testé pour smartphone, tablette et ordinateur.", "en": "Your website is built and tested for phones, tablets and desktops.", "es": "Tu web se desarrolla y prueba para móvil, tableta y ordenador.", "it": "Il sito viene sviluppato e testato per smartphone, tablet e computer."}, "Team": {"fr": "Équipe", "en": "Team", "es": "Equipo", "it": "Team"}, "Strategie, Design und Entwicklung – direkt verbunden.": {"fr": "Stratégie, design et développement réunis.", "en": "Strategy, design and development, connected.", "es": "Estrategia, diseño y desarrollo conectados.", "it": "Strategia, design e sviluppo collegati."}, "Unser Kernteam verbindet strategische Beratung, klare Projektführung, durchdachtes UI/UX-Design und zuverlässige Webentwicklung. Sie arbeiten direkt mit den Verantwortlichen zusammen – persönlich, transparent und ohne unnötige Zwischenstellen.": {"fr": "Notre équipe associe conseil stratégique, gestion de projet, design UI/UX réfléchi et développement fiable. Vous travaillez directement avec les responsables, de façon personnelle et transparente.", "en": "Our core team combines strategic advice, clear project management, thoughtful UI/UX design and reliable web development. You work directly with those responsible, personally and transparently.", "es": "Nuestro equipo combina asesoramiento estratégico, gestión clara, diseño UI/UX y desarrollo fiable. Trabajas directamente con los responsables de forma personal y transparente.", "it": "Il nostro team unisce consulenza strategica, gestione chiara, design UI/UX curato e sviluppo affidabile. Lavori direttamente con i responsabili, in modo personale e trasparente."}, "Founder / Strategy Director": {"fr": "Fondateur / Directeur de la stratégie", "en": "Founder / Strategy Director", "es": "Fundador / Director de estrategia", "it": "Fondatore / Direttore strategico"}, "Creative Director": {"fr": "Directeur créatif", "en": "Creative Director", "es": "Director creativo", "it": "Direttore creativo"}, "Lead Developer": {"fr": "Développeur principal", "en": "Lead Developer", "es": "Desarrollador principal", "it": "Sviluppatore principale"}, "Bereit für professionelles Webdesign": {"fr": "Prêt pour un site professionnel", "en": "Ready for professional web design", "es": "¿Listo para una web profesional", "it": "Pronto per un sito professionale"}, "für Ihr Unternehmen?": {"fr": "pour votre entreprise ?", "en": "for your business?", "es": "para tu empresa?", "it": "per la tua azienda?"}, "Erzählen Sie uns von Ihrer Website, Landingpage oder Ihrem Online-Shop. Wir melden uns persönlich und besprechen die Ziele, Anforderungen und nächsten Schritte Ihres Webprojekts.": {"fr": "Parlez-nous de votre site, landing page ou boutique. Nous vous recontactons personnellement pour discuter des objectifs, des besoins et des prochaines étapes.", "en": "Tell us about your website, landing page or online store. We will contact you personally to discuss goals, requirements and next steps.", "es": "Cuéntanos sobre tu web, landing page o tienda online. Te contactaremos personalmente para hablar de objetivos, requisitos y próximos pasos.", "it": "Parlaci del tuo sito, landing page o negozio online. Ti contatteremo personalmente per discutere obiettivi, requisiti e prossimi passi."}, "Webdesign-Projekt starten": {"fr": "Démarrer mon projet web", "en": "Start your web project", "es": "Iniciar mi proyecto web", "it": "Avvia il tuo progetto web"}, "Webprojekt unverbindlich anfragen": {"fr": "Demander un projet sans engagement", "en": "Make a no-obligation enquiry", "es": "Consulta sin compromiso", "it": "Richiedi informazioni senza impegno"}, "Direkt schreiben": {"fr": "Nous écrire directement", "en": "Write to us directly", "es": "Escríbenos directamente", "it": "Scrivici direttamente"}, "Erzählen Sie uns von Ihrem Projekt.": {"fr": "Parlez-nous de votre projet.", "en": "Tell us about your project.", "es": "Cuéntanos tu proyecto.", "it": "Parlaci del tuo progetto."}, "Füllen Sie das Formular aus. Wir melden uns persönlich bei Ihnen und besprechen die nächsten Schritte.": {"fr": "Remplissez le formulaire. Nous vous recontacterons personnellement pour discuter des prochaines étapes.", "en": "Fill in the form. We will contact you personally to discuss the next steps.", "es": "Rellena el formulario. Te contactaremos personalmente para hablar de los próximos pasos.", "it": "Compila il modulo. Ti contatteremo personalmente per discutere i prossimi passi."}, "Vorname & Nachname": {"fr": "Prénom et nom", "en": "First and last name", "es": "Nombre y apellidos", "it": "Nome e cognome"}, "Bitte geben Sie Ihren Vor- und Nachnamen ein.": {"fr": "Veuillez indiquer votre prénom et votre nom.", "en": "Please enter your first and last name.", "es": "Introduce tu nombre y apellidos.", "it": "Inserisci nome e cognome."}, "Unternehmen / Firmenname": {"fr": "Entreprise / Raison sociale", "en": "Company / Business name", "es": "Empresa / Razón social", "it": "Azienda / Ragione sociale"}, "E-Mail-Adresse": {"fr": "Adresse e-mail", "en": "Email address", "es": "Correo electrónico", "it": "Indirizzo email"}, "Bitte geben Sie eine gültige E-Mail-Adresse ein.": {"fr": "Veuillez saisir une adresse e-mail valide.", "en": "Please enter a valid email address.", "es": "Introduce un correo válido.", "it": "Inserisci un indirizzo email valido."}, "Telefonnummer": {"fr": "Numéro de téléphone", "en": "Phone number", "es": "Número de teléfono", "it": "Numero di telefono"}, "Bitte geben Sie Ihre Telefonnummer ein.": {"fr": "Veuillez saisir votre numéro de téléphone.", "en": "Please enter your phone number.", "es": "Introduce tu número de teléfono.", "it": "Inserisci il numero di telefono."}, "Bestehende Website": {"fr": "Site web existant", "en": "Existing website", "es": "Sitio web actual", "it": "Sito web esistente"}, "Kurze Beschreibung des Projekts": {"fr": "Brève description du projet", "en": "Brief project description", "es": "Breve descripción del proyecto", "it": "Breve descrizione del progetto"}, "Bitte beschreiben Sie Ihr Projekt kurz.": {"fr": "Veuillez décrire brièvement votre projet.", "en": "Please briefly describe your project.", "es": "Describe brevemente tu proyecto.", "it": "Descrivi brevemente il progetto."}, "Anfrage senden": {"fr": "Envoyer la demande", "en": "Send enquiry", "es": "Enviar solicitud", "it": "Invia richiesta"}, "Vielen Dank für Ihre Anfrage.": {"fr": "Merci pour votre demande.", "en": "Thank you for your enquiry.", "es": "Gracias por tu solicitud.", "it": "Grazie per la tua richiesta."}, "Ihre Nachricht wurde erfolgreich gesendet. Wir melden uns so bald wie möglich bei Ihnen.": {"fr": "Votre message a bien été envoyé. Nous vous répondrons dès que possible.", "en": "Your message was sent successfully. We will get back to you as soon as possible.", "es": "Tu mensaje se ha enviado correctamente. Te responderemos lo antes posible.", "it": "Il messaggio è stato inviato correttamente. Ti risponderemo al più presto."}, "Individuelles Webdesign und responsive Webentwicklung für Unternehmen in der Schweiz.": {"fr": "Webdesign sur mesure et développement responsive pour les entreprises en Suisse.", "en": "Custom web design and responsive development for businesses in Switzerland.", "es": "Diseño web a medida y desarrollo adaptable para empresas en Suiza.", "it": "Web design su misura e sviluppo responsive per aziende in Svizzera."}, "Navigation": {"fr": "Navigation", "en": "Navigation", "es": "Navegación", "it": "Navigazione"}, "Rechtliches": {"fr": "Informations légales", "en": "Legal", "es": "Información legal", "it": "Informazioni legali"}, "Impressum": {"fr": "Mentions légales", "en": "Legal notice", "es": "Aviso legal", "it": "Note legali"}, "Datenschutz": {"fr": "Confidentialité", "en": "Privacy", "es": "Privacidad", "it": "Privacy"}, "AGB": {"fr": "Conditions générales", "en": "Terms and conditions", "es": "Condiciones generales", "it": "Condizioni generali"}, "Digital Concepts. Alle Rechte vorbehalten.": {"fr": "Digital Concepts. Tous droits réservés.", "en": "Digital Concepts. All rights reserved.", "es": "Digital Concepts. Todos los derechos reservados.", "it": "Digital Concepts. Tutti i diritti riservati."}, "Schweiz": {"fr": "Suisse", "en": "Switzerland", "es": "Suiza", "it": "Svizzera"}, "Mohammed ist der erste Ansprechpartner für unsere Kunden. Er nimmt sich die Zeit, ihre Ziele und Vorstellungen genau zu verstehen, entwickelt passende Konzepte und begleitet jedes Projekt von der ersten Idee bis zum erfolgreichen Abschluss. Besonders wichtig sind ihm eine persönliche Zusammenarbeit, transparente Kommunikation und ein Ergebnis, mit dem der Kunde langfristig zufrieden ist.": {"fr": "Mohammed est le premier interlocuteur de nos clients. Il prend le temps de comprendre précisément leurs objectifs et leurs attentes, conçoit des solutions adaptées et accompagne chaque projet, de la première idée à sa réalisation. Il accorde une attention particulière à la qualité de la relation, à la transparence des échanges et à un résultat qui apporte une satisfaction durable au client.", "en": "Mohammed is our clients’ first point of contact. He takes the time to fully understand their goals and vision, develops tailored concepts and guides each project from the initial idea through to successful completion. He places particular importance on a personal working relationship, transparent communication and results that clients remain happy with over time.", "es": "Mohammed es el primer punto de contacto de nuestros clientes. Dedica el tiempo necesario a comprender a fondo sus objetivos y expectativas, desarrolla propuestas a medida y acompaña cada proyecto desde la primera idea hasta su culminación. Para él, lo esencial es una colaboración cercana, una comunicación transparente y un resultado que satisfaga al cliente a largo plazo.", "it": "Mohammed è il primo punto di riferimento per i nostri clienti. Dedica il tempo necessario a comprendere a fondo i loro obiettivi e le loro aspettative, sviluppa proposte su misura e segue ogni progetto dalla prima idea fino alla sua realizzazione. Per lui sono fondamentali un rapporto diretto, una comunicazione trasparente e un risultato che soddisfi il cliente nel tempo."}, "Yassine verwandelt Ideen und Konzepte in moderne, leistungsstarke Websites. Er verantwortet die technische und visuelle Umsetzung, optimiert Nutzerführung und Funktionalität und verleiht jedem Projekt den letzten Feinschliff. Dabei legt er besonderen Wert auf durchdachtes Design, saubere Umsetzung und eine Website, die auf jedem Gerät überzeugt.": {"fr": "Yassine transforme les idées et les concepts en sites web modernes et performants. Il assure leur réalisation technique et visuelle, optimise le parcours utilisateur et les fonctionnalités, et soigne les moindres détails de chaque projet. Il privilégie un design réfléchi, un développement rigoureux et une expérience de qualité sur tous les appareils.", "en": "Yassine turns ideas and concepts into modern, high-performing websites. He leads the technical development and visual design, refines the user journey and functionality, and adds the finishing touches to every project. His focus is on thoughtful design, clean implementation and a website that delivers an excellent experience on every device.", "es": "Yassine transforma ideas y conceptos en sitios web modernos y de alto rendimiento. Se encarga del desarrollo técnico y del diseño visual, optimiza la navegación y las funcionalidades, y cuida los últimos detalles de cada proyecto. Da especial importancia a un diseño bien pensado, una implementación cuidada y una experiencia de calidad en cualquier dispositivo.", "it": "Yassine trasforma idee e concetti in siti web moderni e performanti. Cura lo sviluppo tecnico e il design visivo, ottimizza i percorsi di navigazione e le funzionalità e rifinisce ogni dettaglio del progetto. Dedica particolare attenzione a un design ragionato, a uno sviluppo accurato e a un’esperienza di qualità su ogni dispositivo."}, "Founder / Strategy & Client Relations": {"fr": "Fondateur / Stratégie & Relation client", "en": "Founder / Strategy & Client Relations", "es": "Fundador / Estrategia y Relación con el cliente", "it": "Fondatore / Strategia e Relazioni con i clienti"}, "Web Developer / Creative Director": {"fr": "Développeur web / Directeur créatif", "en": "Web Developer / Creative Director", "es": "Desarrollador web / Director creativo", "it": "Sviluppatore web / Direttore creativo"}, "Digital Concepts entwickelt individuelle Websites, Landingpages und Online-Shops für Schweizer Unternehmen. Klar gestaltet, responsiv umgesetzt und auf Ihre Ziele ausgerichtet.": {"fr": "Digital Concepts crée des sites web, des landing pages et des boutiques en ligne sur mesure pour les entreprises suisses. Un design clair, une expérience adaptée à chaque écran et vos objectifs au cœur du projet.", "en": "Digital Concepts builds bespoke websites, landing pages and online stores for Swiss businesses. Clear design, responsive development and a focus on your goals.", "es": "Digital Concepts crea sitios web, landing pages y tiendas online a medida para empresas suizas. Diseño claro, adaptación a cada pantalla y un enfoque centrado en sus objetivos.", "it": "Digital Concepts realizza siti web, landing page e negozi online su misura per le aziende svizzere. Design chiaro, sviluppo responsive e i vostri obiettivi al centro del progetto."}, "Wir verbinden durchdachtes Webdesign, effiziente Entwicklung und klare Kommunikation. So entsteht eine Website, die zu Ihrem Unternehmen passt und auf jedem Gerät überzeugt.": {"fr": "Nous associons un design réfléchi, un développement efficace et une communication claire pour créer un site fidèle à votre entreprise, agréable à utiliser sur tous les appareils.", "en": "We combine thoughtful web design, efficient development and clear communication to create a website that fits your business and works beautifully on every device.", "es": "Combinamos un diseño web cuidado, un desarrollo eficiente y una comunicación clara para crear un sitio que refleje su empresa y ofrezca una gran experiencia en cualquier dispositivo.", "it": "Uniamo web design ragionato, sviluppo efficiente e comunicazione chiara per creare un sito che rispecchi la vostra azienda e offra un’ottima esperienza su ogni dispositivo."}, "Gestaltung, Struktur und Nutzerführung werden gezielt auf Ihre Marke und Ihr Unternehmen abgestimmt.": {"fr": "Le design, la structure et le parcours utilisateur sont pensés pour votre marque et votre entreprise.", "en": "The design, structure and user journey are tailored to your brand and business.", "es": "El diseño, la estructura y la navegación se adaptan a su marca y a su empresa.", "it": "Design, struttura e percorsi di navigazione sono studiati per il vostro marchio e la vostra azienda."}, "Ihre Website bleibt auf Smartphone, Tablet und Desktop übersichtlich und einfach zu bedienen.": {"fr": "Votre site reste clair et facile à utiliser sur smartphone, tablette et ordinateur.", "en": "Your website stays clear and easy to use on smartphones, tablets and desktops.", "es": "Su sitio web se mantiene claro y fácil de usar en móviles, tabletas y ordenadores.", "it": "Il vostro sito rimane chiaro e facile da usare su smartphone, tablet e computer."}, "Klare Abläufe ermöglichen eine professionelle Umsetzung ohne unnötigen Agentur-Overhead.": {"fr": "Une organisation claire permet une réalisation professionnelle, sans les lourdeurs inutiles d’une agence.", "en": "Clear processes ensure professional delivery without unnecessary agency overhead.", "es": "Unos procesos claros permiten una ejecución profesional sin los costes ni la complejidad innecesarios de una agencia.", "it": "Processi chiari consentono una realizzazione professionale senza costi e complessità superflui di agenzia."}, "Eine veraltete Website kann Vertrauen kosten. Mit einem Relaunch schaffen wir einen modernen, schnellen und klar strukturierten Auftritt für Ihr Unternehmen.": {"fr": "Un site vieillissant peut nuire à la confiance. Avec une refonte, nous offrons à votre entreprise une présence en ligne moderne, rapide et bien structurée.", "en": "An outdated website can undermine trust. A redesign gives your business a modern, fast and clearly structured online presence.", "es": "Un sitio anticuado puede restar confianza. Con una renovación, damos a su empresa una presencia online moderna, rápida y bien estructurada.", "it": "Un sito datato può compromettere la fiducia. Con un restyling diamo alla vostra azienda una presenza online moderna, veloce e ben strutturata."}, "Muster AG": {"fr": "Entreprise Démo SA", "en": "Example Ltd", "es": "Empresa Ejemplo SA", "it": "Azienda Esempio SA"}, "Konzeptbeispiel für eine klar strukturierte Unternehmenswebsite im Dienstleistungsbereich.": {"fr": "Exemple de concept pour un site d’entreprise clair et structuré dans le secteur des services.", "en": "A concept for a clearly structured business website in the service sector.", "es": "Ejemplo de concepto para un sitio empresarial bien estructurado en el sector de los servicios.", "it": "Esempio di concept per un sito aziendale ben strutturato nel settore dei servizi."}, "Konzeptbeispiel für einen responsiven Online-Shop mit übersichtlicher Produktnavigation.": {"fr": "Exemple de concept pour une boutique en ligne responsive, avec une navigation intuitive entre les produits.", "en": "A concept for a responsive online store with clear, intuitive product navigation.", "es": "Ejemplo de concepto para una tienda online adaptable con una navegación de productos clara e intuitiva.", "it": "Esempio di concept per un negozio online responsive con una navigazione dei prodotti chiara e intuitiva."}, "Konzeptbeispiel für eine fokussierte Landingpage mit klarer Handlungsaufforderung.": {"fr": "Exemple de concept pour une landing page ciblée, avec un appel à l’action clair.", "en": "A concept for a focused landing page with a clear call to action.", "es": "Ejemplo de concepto para una landing page enfocada en un objetivo y con una llamada a la acción clara.", "it": "Esempio di concept per una landing page mirata con un invito all’azione chiaro."}, "Fünf klare Schritte führen vom ersten Gespräch bis zum Launch. Dabei wissen Sie jederzeit, wo Ihr Projekt steht.": {"fr": "Cinq étapes claires, du premier échange à la mise en ligne. Vous savez à tout moment où en est votre projet.", "en": "Five clear steps take you from our first conversation to launch. You always know where your project stands.", "es": "Cinco pasos claros, desde la primera conversación hasta el lanzamiento. En todo momento sabrá en qué punto se encuentra su proyecto.", "it": "Cinque passaggi chiari, dal primo incontro alla pubblicazione. Saprete sempre a che punto è il vostro progetto."}, "Launch": {"fr": "Mise en ligne", "en": "Launch", "es": "Lanzamiento", "it": "Pubblicazione"}, "Landingpage": {"fr": "Landing page", "en": "Landing page", "es": "Página de destino", "it": "Landing page"}, "Persönlicher Austausch, klare Entscheidungen und ein nachvollziehbarer Ablauf bilden die Grundlage jedes Projekts.": {"fr": "Des échanges directs, des décisions claires et un déroulement transparent : les bases de chaque projet.", "en": "Personal communication, clear decisions and a transparent process form the foundation of every project.", "es": "Un trato cercano, decisiones claras y un proceso transparente son la base de cada proyecto.", "it": "Dialogo diretto, decisioni chiare e un processo trasparente sono alla base di ogni progetto."}, "Eine ruhige Gestaltung und eine klare Hierarchie lenken den Blick auf die wesentlichen Inhalte.": {"fr": "Un design épuré et une hiérarchie claire attirent l’attention sur l’essentiel.", "en": "A restrained design and clear hierarchy draw attention to the content that matters.", "es": "Un diseño sobrio y una jerarquía clara dirigen la atención hacia los contenidos esenciales.", "it": "Un design sobrio e una gerarchia chiara guidano l’attenzione verso i contenuti essenziali."}, "Sie sprechen mit den Personen, die Ihre Website konzipieren, gestalten und entwickeln.": {"fr": "Vous échangez directement avec les personnes qui conçoivent, dessinent et développent votre site.", "en": "You speak directly with the people who plan, design and develop your website.", "es": "Habla directamente con quienes planifican, diseñan y desarrollan su sitio web.", "it": "Parlate direttamente con chi progetta, disegna e sviluppa il vostro sito."}, "Funktionen und Umfang richten sich nach Ihrem Vorhaben, nicht nach einem starren Paket.": {"fr": "Les fonctionnalités et l’envergure du projet s’adaptent à vos besoins, sans formule rigide.", "en": "Features and scope are shaped around your project, rather than a fixed package.", "es": "Las funcionalidades y el alcance se adaptan a su proyecto, sin paquetes rígidos.", "it": "Funzionalità e dimensioni si adattano al vostro progetto, senza pacchetti rigidi."}, "Strukturierte Prozesse sorgen für eine zielgerichtete und verlässliche Entwicklung.": {"fr": "Des processus structurés assurent un développement efficace et fiable.", "en": "Structured processes keep development focused and reliable.", "es": "Unos procesos estructurados garantizan un desarrollo enfocado y fiable.", "it": "Processi strutturati garantiscono uno sviluppo mirato e affidabile."}, "Sie wissen, woran wir arbeiten, welche Entscheidungen anstehen und was als Nächstes folgt.": {"fr": "Vous savez sur quoi nous travaillons, quelles décisions prendre et quelles sont les prochaines étapes.", "en": "You know what we are working on, which decisions need to be made and what comes next.", "es": "Sabe en qué estamos trabajando, qué decisiones hay que tomar y cuáles son los siguientes pasos.", "it": "Sapete a cosa stiamo lavorando, quali decisioni prendere e quali saranno i prossimi passi."}, "Klare Inhalte helfen Besucherinnen und Besuchern, schnell die richtigen Informationen zu finden.": {"fr": "Des contenus clairs permettent à vos visiteurs de trouver rapidement les informations qu’ils recherchent.", "en": "Clear content helps visitors quickly find the information they need.", "es": "Unos contenidos claros ayudan a los visitantes a encontrar rápidamente la información que buscan.", "it": "Contenuti chiari aiutano i visitatori a trovare rapidamente le informazioni che cercano."}, "Strategie, Design und Entwicklung greifen bei uns direkt ineinander. Sie arbeiten persönlich mit den Verantwortlichen Ihres Projekts zusammen.": {"fr": "Chez nous, stratégie, design et développement avancent ensemble. Vous échangez directement avec les personnes responsables de votre projet.", "en": "Strategy, design and development work hand in hand. You collaborate directly with the people responsible for your project.", "es": "La estrategia, el diseño y el desarrollo trabajan de la mano. Colabora directamente con las personas responsables de su proyecto.", "it": "Strategia, design e sviluppo lavorano insieme. Collaborate direttamente con i responsabili del vostro progetto."}, "Erzählen Sie uns von Ihrem Vorhaben. Wir melden uns persönlich und besprechen gemeinsam die nächsten Schritte.": {"fr": "Parlez-nous de votre projet. Nous vous recontacterons personnellement pour définir ensemble les prochaines étapes.", "en": "Tell us about your plans. We will get in touch personally to discuss the next steps together.", "es": "Cuéntenos qué tiene en mente. Nos pondremos en contacto personalmente para definir juntos los siguientes pasos.", "it": "Raccontateci la vostra idea. Vi contatteremo personalmente per definire insieme i prossimi passi."}, "Beschreiben Sie kurz Ihr Vorhaben. Wir melden uns persönlich und besprechen die nächsten Schritte.": {"fr": "Décrivez-nous brièvement votre projet. Nous vous recontacterons personnellement pour discuter des prochaines étapes.", "en": "Briefly describe your project. We will get in touch personally to discuss the next steps.", "es": "Describa brevemente su proyecto. Nos pondremos en contacto personalmente para hablar de los siguientes pasos.", "it": "Descrivete brevemente il vostro progetto. Vi contatteremo personalmente per discutere i prossimi passi."}, "Hauptnavigation": {"fr": "Navigation principale", "en": "Main navigation", "es": "Navegación principal", "it": "Navigazione principale"}, "Menü": {"fr": "Menu", "en": "Menu", "es": "Menú", "it": "Menu"}, "Websites, die": {"fr": "Des sites web qui", "en": "Websites that", "es": "Sitios web que", "it": "Siti web che"}, "Unternehmen": {"fr": "font avancer", "en": "move businesses", "es": "hacen avanzar", "it": "fanno crescere"}, "voranbringen.": {"fr": "les entreprises.", "en": "forward.", "es": "a las empresas.", "it": "le aziende."}, "Projekte ansehen": {"fr": "Voir les projets", "en": "View projects", "es": "Ver proyectos", "it": "Vedi i progetti"}, "Websites nach Mass. Klar umgesetzt.": {"fr": "Des sites sur mesure. Une réalisation claire.", "en": "Websites made to measure. Clearly delivered.", "es": "Sitios web a medida. Una ejecución clara.", "it": "Siti web su misura. Realizzati con chiarezza."}, "Websites, Landingpages und Online-Shops.": {"fr": "Sites web, landing pages et boutiques en ligne.", "en": "Websites, landing pages and online stores.", "es": "Sitios web, landing pages y tiendas online.", "it": "Siti web, landing page e negozi online."}, "Fokussierte Seiten für Kampagnen, Dienstleistungen, Produkte und neue Angebote.": {"fr": "Des pages ciblées pour vos campagnes, services, produits et nouvelles offres.", "en": "Focused pages for campaigns, services, products and new offers.", "es": "Páginas enfocadas en campañas, servicios, productos y nuevas ofertas.", "it": "Pagine mirate per campagne, servizi, prodotti e nuove offerte."}, "Professionelle Auftritte, die Vertrauen schaffen und Ihre Leistungen verständlich präsentieren.": {"fr": "Des sites professionnels qui inspirent confiance et présentent clairement vos services.", "en": "Professional websites that build trust and explain your services clearly.", "es": "Sitios profesionales que generan confianza y presentan sus servicios con claridad.", "it": "Siti professionali che ispirano fiducia e presentano chiaramente i vostri servizi."}, "Übersichtliche Shops mit klarer Navigation und überzeugender Produktdarstellung.": {"fr": "Des boutiques claires, faciles à parcourir, qui mettent vos produits en valeur.", "en": "Easy-to-navigate stores that showcase your products effectively.", "es": "Tiendas fáciles de recorrer que presentan sus productos de forma convincente.", "it": "Negozi facili da navigare che valorizzano i vostri prodotti."}, "Passende Funktionen und digitale Lösungen für besondere Projektanforderungen.": {"fr": "Des fonctionnalités et solutions numériques adaptées aux besoins particuliers de votre projet.", "en": "Features and digital solutions tailored to the specific needs of your project.", "es": "Funciones y soluciones digitales adaptadas a las necesidades específicas de su proyecto.", "it": "Funzioni e soluzioni digitali adatte alle esigenze specifiche del vostro progetto."}, "Zeit für einen neuen digitalen Auftritt?": {"fr": "Il est temps de renouveler votre présence en ligne ?", "en": "Time for a fresh online presence?", "es": "¿Ha llegado el momento de renovar su presencia digital?", "it": "È il momento di rinnovare la vostra presenza online?"}, "Beispielhafte Webkonzepte.": {"fr": "Exemples de concepts web.", "en": "Examples of web concepts.", "es": "Ejemplos de conceptos web.", "it": "Esempi di progetti web."}, "Konzept ansehen": {"fr": "Voir le concept", "en": "View concept", "es": "Ver concepto", "it": "Vedi il concept"}, "So entsteht Ihre neue Website.": {"fr": "Voici comment prend forme votre nouveau site.", "en": "How your new website takes shape.", "es": "Así nace su nuevo sitio web.", "it": "Come prende forma il vostro nuovo sito."}, "Wir lernen Ihr Unternehmen, Ihre Zielgruppen und die Ziele der neuen Website kennen.": {"fr": "Nous découvrons votre entreprise, vos publics cibles et les objectifs de votre nouveau site.", "en": "We get to know your business, your audiences and the goals of your new website.", "es": "Conocemos su empresa, su público objetivo y los objetivos del nuevo sitio web.", "it": "Conosciamo la vostra azienda, il pubblico di riferimento e gli obiettivi del nuovo sito."}, "Wir gestalten die Website und setzen sie responsiv und technisch sauber um.": {"fr": "Nous concevons le site et le réalisons avec soin pour tous les écrans.", "en": "We design the website and build it responsively with clean technical implementation.", "es": "Diseñamos el sitio y lo desarrollamos con cuidado para todos los dispositivos.", "it": "Progettiamo il sito e lo realizziamo in modo responsive e tecnicamente accurato."}, "Wir prüfen Darstellung, Ladegeschwindigkeit, Lesbarkeit und Bedienbarkeit auf allen wichtigen Geräten.": {"fr": "Nous vérifions l’affichage, la vitesse de chargement, la lisibilité et la facilité d’utilisation sur les principaux appareils.", "en": "We check display, loading speed, readability and usability across the main devices.", "es": "Comprobamos la visualización, la velocidad de carga, la legibilidad y la facilidad de uso en los principales dispositivos.", "it": "Verifichiamo visualizzazione, velocità di caricamento, leggibilità e facilità d’uso sui principali dispositivi."}, "Was die Zusammenarbeit auszeichnet.": {"fr": "Ce qui distingue notre collaboration.", "en": "What sets our collaboration apart.", "es": "Lo que distingue nuestra colaboración.", "it": "Cosa distingue la nostra collaborazione."}, "Klares Design": {"fr": "Un design clair", "en": "Clear design", "es": "Diseño claro", "it": "Design chiaro"}, "Direkte Zusammenarbeit": {"fr": "Une collaboration directe", "en": "Direct collaboration", "es": "Colaboración directa", "it": "Collaborazione diretta"}, "Kurze Wege": {"fr": "Des échanges directs", "en": "Direct communication", "es": "Comunicación directa", "it": "Comunicazione diretta"}, "Passende Lösungen": {"fr": "Des solutions adaptées", "en": "Tailored solutions", "es": "Soluciones adecuadas", "it": "Soluzioni su misura"}, "Transparenter Ablauf": {"fr": "Un processus transparent", "en": "A transparent process", "es": "Un proceso transparente", "it": "Un processo trasparente"}, "Gute Nutzerführung": {"fr": "Une navigation intuitive", "en": "Intuitive navigation", "es": "Navegación intuitiva", "it": "Navigazione intuitiva"}, "Für jedes Gerät": {"fr": "Adapté à chaque écran", "en": "Built for every device", "es": "Para todos los dispositivos", "it": "Per ogni dispositivo"}, "Bereit für eine Website,": {"fr": "Prêt pour un site web", "en": "Ready for a website", "es": "¿Listo para un sitio web", "it": "Pronti per un sito web"}, "die zu Ihrem Unternehmen passt?": {"fr": "adapté à votre entreprise ?", "en": "that fits your business?", "es": "a la medida de su empresa?", "it": "adatto alla vostra azienda?"}, "Projekt anfragen": {"fr": "Parlons de votre projet", "en": "Enquire about a project", "es": "Consúltenos sobre su proyecto", "it": "Parliamo del vostro progetto"}, "Vor- und Nachname": {"fr": "Prénom et nom", "en": "First and last name", "es": "Nombre y apellidos", "it": "Nome e cognome"}};

Object.assign(window.DC_TRANSLATIONS,{"Dashboards & Verwaltungssysteme": {"fr": "Tableaux de bord & systèmes d’administration", "en": "Dashboards & administration systems", "es": "Paneles de control y administración", "it": "Dashboard e sistemi di amministrazione"}, "Online-Buchungssysteme": {"fr": "Systèmes de réservation en ligne", "en": "Online booking systems", "es": "Sistemas de reservas online", "it": "Sistemi di prenotazione online"}, "Formulare & Datenerfassung": {"fr": "Formulaires & collecte de données", "en": "Forms & data collection", "es": "Formularios y recopilación de datos", "it": "Moduli e raccolta dati"}, "Online-Zahlungssysteme": {"fr": "Systèmes de paiement en ligne", "en": "Online payment systems", "es": "Sistemas de pago online", "it": "Sistemi di pagamento online"}, "Sicherheit & Website-Schutz": {"fr": "Sécurité & protection des sites", "en": "Security & website protection", "es": "Seguridad y protección web", "it": "Sicurezza e protezione dei siti"}, "Migration & technische Überarbeitung": {"fr": "Migration & refonte technique", "en": "Migration & technical redesign", "es": "Migración y renovación técnica", "it": "Migrazione e revisione tecnica"}, "KI & intelligente Automatisierung": {"fr": "Solutions IA & automatisation intelligente", "en": "AI & intelligent automation", "es": "IA y automatización inteligente", "it": "IA e automazione intelligente"}, "Kennzahlen, Kunden und Inhalte an einem Ort verwalten. Ein übersichtlicher Arbeitsbereich, abgestimmt auf Ihr Team.": {"fr": "Pilotez vos indicateurs, vos clients et vos contenus depuis un espace clair, conçu pour les besoins de votre équipe.", "en": "Manage metrics, customers and content in one clear workspace designed around your team.", "es": "Gestiona indicadores, clientes y contenidos en un espacio claro adaptado a tu equipo.", "it": "Gestisci indicatori, clienti e contenuti in uno spazio chiaro pensato per il tuo team."}, "Termine jederzeit online buchen. Mit Verfügbarkeiten, Bestätigungen und Erinnerungen wird die Organisation einfacher.": {"fr": "Permettez à vos clients de réserver à toute heure : disponibilités, confirmations et rappels simplifient votre organisation.", "en": "Let customers book anytime, with availability, confirmations and reminders to simplify scheduling.", "es": "Permite reservar a cualquier hora con disponibilidad, confirmaciones y recordatorios.", "it": "Permetti di prenotare in ogni momento, con disponibilità, conferme e promemoria."}, "Anfragen und Informationen strukturiert erfassen. Individuelle Formulare leiten Daten direkt an die passenden Stellen weiter.": {"fr": "Centralisez les demandes et les informations grâce à des formulaires sur mesure, reliés à vos outils de travail.", "en": "Collect enquiries and information with custom forms connected to your everyday tools.", "es": "Centraliza solicitudes e información con formularios personalizados conectados a tus herramientas.", "it": "Raccogli richieste e informazioni con moduli personalizzati collegati ai tuoi strumenti."}, "Zahlungen, Anzahlungen oder Abonnements in Ihre Website integrieren, mit einem klaren Ablauf für Ihre Kunden.": {"fr": "Intégrez les paiements, acomptes ou abonnements à votre site, avec un parcours simple et rassurant pour vos clients.", "en": "Integrate payments, deposits or subscriptions into your website with a clear customer journey.", "es": "Integra pagos, anticipos o suscripciones con un proceso sencillo para tus clientes.", "it": "Integra pagamenti, acconti o abbonamenti con un percorso semplice per i clienti."}, "Zugänge absichern, Updates durchführen und Backups einrichten, um Risiken zu reduzieren und Ihre Website zu schützen.": {"fr": "Renforcez la protection de votre site : accès sécurisés, mises à jour et sauvegardes pour réduire les risques.", "en": "Reduce risks with secure access, updates and backups that help protect your website.", "es": "Reduce riesgos con accesos seguros, actualizaciones y copias de seguridad.", "it": "Riduci i rischi con accessi sicuri, aggiornamenti e copie di backup."}, "Hosting oder Technologie wechseln und die technische Basis modernisieren. Inhalte und Weiterleitungen werden sorgfältig übernommen.": {"fr": "Changez d’hébergement ou modernisez la base technique de votre site, avec une reprise soignée des contenus et des redirections.", "en": "Move hosting or modernise your technical foundation, with careful content migration and redirects.", "es": "Cambia de alojamiento o moderniza tu web cuidando la migración de contenidos y las redirecciones.", "it": "Cambia hosting o modernizza la base tecnica, curando contenuti e reindirizzamenti."}, "Wiederkehrende Prozesse automatisieren, Ihre Tools verbinden und passende KI-Assistenten integrieren — für mehr Zeit im Alltag.": {"fr": "Automatisez les processus répétitifs, connectez vos outils et intégrez des assistants IA adaptés pour gagner du temps au quotidien.", "en": "Automate repetitive processes, connect your tools and add tailored AI assistants to save time every day.", "es": "Automatiza procesos repetitivos, conecta herramientas e integra asistentes de IA adaptados.", "it": "Automatizza i processi ripetitivi, collega gli strumenti e integra assistenti IA su misura."}, "Wählen Sie eine Lösung, um mehr zu erfahren.": {"fr": "Cliquez sur un service pour découvrir les détails.", "en": "Select a service to explore the details.", "es": "Selecciona un servicio para ver los detalles.", "it": "Seleziona un servizio per scoprire i dettagli."}});

Object.assign(window.DC_TRANSLATIONS,{"Eine Lösung nach Mass?": {"fr": "Un besoin sur mesure ?", "en": "Something tailored to you?", "es": "¿Una solución a medida?", "it": "Una soluzione su misura?"}, "Sie haben eine andere Idee? Diese Leistungen sind nur Beispiele. Erzählen Sie uns von Ihrem Projekt – gemeinsam entwickeln wir eine Lösung für Ihr Unternehmen.": {"fr": "Vous avez une autre idée ? Ces services sont quelques exemples. Parlons de votre projet et imaginons une solution adaptée à votre activité.", "en": "Have another idea? These services are just examples. Tell us about your project and let’s design a solution around your business.", "es": "¿Tienes otra idea? Estos servicios son solo ejemplos. Hablemos de tu proyecto y diseñemos una solución para tu negocio.", "it": "Hai un’altra idea? Questi servizi sono solo alcuni esempi. Parliamo del tuo progetto e creiamo una soluzione adatta alla tua attività."}, "Über Ihr Projekt sprechen": {"fr": "Parlons de votre projet", "en": "Let’s discuss your project", "es": "Hablemos de tu proyecto", "it": "Parliamo del tuo progetto"}});
